import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { batchProductVariantsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await batchProductVariantsWorkflow(req.scope)
    .run({
      input: {
        create: [{
          title: "Small Shirt",
          product_id: "prod_123",
          options: {
            Size: "S"
          },
          prices: [{
            amount: 10,
            currency_code: "usd"
          }]
        }],
        update: [{
          id: "variant_123",
          title: "Red Pants"
        }],
        delete: ["variant_321"]
      }
    })

  res.send(result)
}

